insert into public.lois_use_cases(slug,title,category,summary,steps,standard_config,config_fields,outward,reversible,status) values
('social-media-management','Social media management','Marketing','Plan a week of posts, draft them in your voice, get a person to approve each one, publish through your automation, then learn what worked.','[{"key":"brief","name":"Gather brand voice and goals","kind":"internal","does":"Reads your accepted knowledge and the answers you gave.","why":"Posts should sound like you and serve a goal.","produces":"A one-paragraph brief."},{"key":"plan","name":"Plan the content calendar","kind":"internal","does":"Spreads the week across your platforms and themes.","why":"A plan avoids last-minute posting.","produces":"A calendar with days, platforms and themes."},{"key":"draft","name":"Draft the posts","kind":"internal","does":"Writes one draft per slot.","why":"Drafting is the slow part; a person edits instead of starting blank.","produces":"Draft posts, each labelled as a draft."},{"key":"approve","name":"A person approves each draft","kind":"person","does":"Waits for a named approver who is not the requester.","why":"Public posts cannot be unpublished from people''s feeds.","produces":"Approved or rejected, with a note."},{"key":"publish","name":"Publish through your automation","kind":"external","does":"Sends the approved posts to your connector (Make, n8n or Zapier) to schedule.","why":"The platform accounts live outside LOIS.","produces":"Scheduled or posted confirmations.","outward":true,"reversible":false},{"key":"collect","name":"Collect results","kind":"external","does":"Your automation reports reach and responses back to LOIS.","why":"Without results nothing can be learned.","produces":"Numbers, labelled as reported."},{"key":"learn","name":"Summarise and learn","kind":"internal","does":"Writes a plain summary and proposes a learning to the Knowledge bank for review.","why":"So the next week starts smarter.","produces":"A summary and a pending Knowledge bank entry."}]'::jsonb,'{"tone":"friendly and clear","platforms":"LinkedIn, Instagram","posts_per_week":5,"themes":"tips, behind the scenes, customer stories","approval":"every post"}'::jsonb,'[{"key":"tone","label":"Tone of voice","type":"text","help":"For example: warm and professional."},{"key":"platforms","label":"Platforms","type":"list","help":"Comma separated."},{"key":"posts_per_week","label":"Posts per week","type":"number","help":"1 to 21."},{"key":"themes","label":"Themes","type":"list","help":"Comma separated."},{"key":"approval","label":"Approval","type":"select","options":["every post","weekly batch"],"help":"Live runs always need approval. This sets how often."}]'::jsonb,true,false,'template'),
('orders-and-invoicing','Distributor orders and invoicing','Sales and finance','Take an order, check it, prepare a quote, get approval, create the invoice and receipt, and follow up on payment.','[{"key":"intake","name":"Read the order","kind":"internal","does":"Pulls customer, items and quantities from the order text.","why":"Retyping orders causes errors.","produces":"A structured order."},{"key":"check","name":"Check stock, price and credit","kind":"external","does":"Asks your system (for example Odoo or a sheet) whether items are available and the customer is in good standing.","why":"Stops promises you cannot keep.","produces":"Availability and credit flags, labelled as reported."},{"key":"quote","name":"Prepare the quote","kind":"internal","does":"Applies your price list and terms.","why":"Consistent pricing.","produces":"A draft quote."},{"key":"approve","name":"A person approves the quote","kind":"person","does":"Waits for an approver who is not the requester.","why":"A quote is a commitment.","produces":"Approved or rejected, with a note."},{"key":"invoice","name":"Create the invoice and send it","kind":"external","does":"Creates the invoice in your accounting system and emails the customer.","why":"Customers pay what they receive.","produces":"Invoice number and delivery confirmation.","outward":true,"reversible":false},{"key":"followup","name":"Follow up on payment","kind":"internal","does":"Drafts polite reminders on the due date.","why":"Late payment is usually forgetfulness.","produces":"Reminder drafts for a person to send."},{"key":"receipt","name":"Record payment and issue the receipt","kind":"external","does":"Marks paid and sends a receipt.","why":"A clean record.","produces":"Receipt number.","outward":true,"reversible":false}]'::jsonb,'{"currency":"KES","payment_terms":"14 days","reminder_after_days":3,"approval":"every quote","tax":"VAT 16%"}'::jsonb,'[{"key":"currency","label":"Currency","type":"text","help":"For example KES."},{"key":"payment_terms","label":"Payment terms","type":"text","help":"For example 14 days."},{"key":"reminder_after_days","label":"Reminder after (days)","type":"number","help":"Days past due."},{"key":"tax","label":"Tax","type":"text","help":"Name and rate."},{"key":"approval","label":"Approval","type":"select","options":["every quote","quotes above a limit"],"help":"Live runs always need approval."}]'::jsonb,true,false,'template'),
('lead-capture-and-follow-up','Lead capture and follow-up','Sales','Catch an enquiry, score it, route it to the right person, draft a follow-up, get approval, send, and track the outcome.','[{"key":"capture","name":"Capture the enquiry","kind":"external","does":"Your form or inbox sends the enquiry to LOIS.","why":"One place for every lead.","produces":"A lead record."},{"key":"score","name":"Score and route","kind":"internal","does":"Applies plain rules (budget, urgency, fit) and picks an owner.","why":"The right person answers first.","produces":"Score with reasons, and an owner."},{"key":"draft","name":"Draft the reply","kind":"internal","does":"Writes a reply using your accepted knowledge.","why":"Fast, consistent answers.","produces":"A draft reply."},{"key":"approve","name":"A person approves the reply","kind":"person","does":"Waits for an approver who is not the requester.","why":"Customers see exactly what is sent.","produces":"Approved or rejected, with a note."},{"key":"send","name":"Send and log","kind":"external","does":"Sends from your email or CRM and records it.","why":"Keeps the history in one place.","produces":"Sent confirmation.","outward":true,"reversible":false},{"key":"track","name":"Track and learn","kind":"internal","does":"Records the outcome and proposes a learning to the Knowledge bank.","why":"Improves scoring over time.","produces":"Outcome and a pending Knowledge bank entry."}]'::jsonb,'{"reply_within_hours":4,"tone":"helpful and direct","score_rules":"budget stated, urgent, in our service area","approval":"every reply"}'::jsonb,'[{"key":"reply_within_hours","label":"Reply within (hours)","type":"number","help":"Your promise to customers."},{"key":"tone","label":"Tone","type":"text","help":"For example: warm."},{"key":"score_rules","label":"What makes a good lead","type":"list","help":"Comma separated."},{"key":"approval","label":"Approval","type":"select","options":["every reply","low-risk replies only"],"help":"Live runs always need approval."}]'::jsonb,true,false,'template')
